def _present_of(key: str) -> tuple[str, list[str]] | None:
    """The present of a future form that LEX has: بـ before it (بتسأل, بيشوف), and مـ as well before "we" (منيجي). "I"
    loses its ا (اسأل -> بسأل). The prefix takes the vowel the form needs: בַּסְאַל, בְּתִסְאַל, בִּתְשוּף, בִּיסְאַל."""
    body, _, tag = key[1:].partition("#")
    tag = "#" + tag if tag else ""
    if key[:1] == "ب" and body[:1] not in "تني":   # "I": the future's ا, or its آ (باكل)
        for k in ("ا" + body + tag, "ا" + body + "#i", "آ" + body[1:] + tag):   # اسأل alone is the imperative: the future is اسأل#i
            if k in LEX and LEX[k][0].startswith("אַ"):
                tr, ipas = LEX[k]
                return "ב\u05b7\u05bc" + tr[2:], ["b " + i.removeprefix("ʔ ") for i in ipas]
        return None
    if not (key[:1] == "ب" and body[:1] in "تني" or key[:1] == "م" and body[:1] == "ن") or body + tag not in LEX:
        return None
    tr, ipas = LEX[body + tag]
    he, dot, ipa = ("ב", "\u05bc", "b") if key[0] == "ب" else ("מ", "", "m")   # the vowel goes under the letter, before its dagesh
    if tr[:2] in ("יִ", "יְ"):   # يسأل, يشوف: the י is only heard as the prefix's vowel
        heard = [i.removeprefix("j i ").removeprefix("j ").removeprefix("i ") for i in ipas]
        return he + "\u05b4" + dot + "י" + tr[2:], list(dict.fromkeys(f"{ipa} i {i}" for i in heard))
    if tr[1:2] == "ְ":        # تشوف, نروح: two consonants open the form, so the prefix has a vowel
        return he + "\u05b4" + dot + tr, [f"{ipa} i {i}" for i in ipas]
    return he + "\u05b0" + dot + tr, [f"{ipa} {i}" for i in ipas]


def _word(token: str) -> tuple[str, str, list[str]]:
    """(Arabic as shown, transliteration, IPA readings) of one word of a sentence."""
    key = token.rstrip("".join(PUNCT))
    tail = token[len(key):]
    tr_tail = "".join(PUNCT[c] for c in tail)
    if key in LEX:
        tr, ipas = LEX[key]
    elif _present_of(key):   # بـ on a future form: the present
        tr, ipas = _present_of(key)
    elif key.startswith("و") and (key[1:] in LEX or _present_of(key[1:])):   # "and" written on the word
        tr, ipas = LEX.get(key[1:]) or _present_of(key[1:])
        tr, ipas = "וּ" + tr, ["u " + i for i in ipas]
    else:
        raise KeyError(f"workbook word not in LEX: {key}")
    return key.partition("#")[0] + tail, tr + tr_tail, ipas


def _variants(words: list[tuple[str, str, list[str]]]) -> list[tuple[str, str]]:
    """Every combination of the words' readings; when that is too many, the main reading throughout
    and then each word's n-th reading together (a speaker who says ق as q says it in every word)."""
    ar = " ".join(a for a, _, _ in words)
    readings = [ipas for _, _, ipas in words]
    count = 1
    for r in readings:
        count *= len(r)
    if count <= MAX_VARIANTS:
        combos = itertools.product(*readings)
    else:
        combos = dict.fromkeys(tuple(r[min(n, len(r) - 1)] for r in readings)
                               for n in range(max(map(len, readings))))
    return [(ar, " | ".join(c)) for c in combos]


def workbook_phrases() -> list[dict]:
    """The lessons' items as phrases (see phrases.py). `seq` keeps an ordered topic's order and
    `read` marks the Arabic -> Hebrew ones, where the page shows `tr` and hides `he`;
    `he_say` is the pointed Hebrew for the prompt voice, where the plain text is misread."""
    out = []
    for key, topics in LESSONS.items():
        for tid, _, kind, in_order, items in topics:
            for seq, (he, sentence, *he_say) in enumerate(items, 1):
                words = [_word(t) for t in sentence.split()]
                phrase = dict(cat=f"l{lesson_id(*key)}-{tid}", he=he, tr=" ".join(t for _, t, _ in words),
                              variants=_variants(words), read=kind == "read")
                say = _voiced(he_say[0] if he_say else he)
                if say != he:
                    phrase["he_say"] = say
                if in_order:
                    phrase["seq"] = seq
                out.append(phrase)
    for game in GAMES:
        for he, sentence, *he_say in GAME_ITEMS[game["id"]]:
            words = [_word(t) for t in sentence.split()]
            phrase = dict(cat=game["id"], he=he, tr=" ".join(t for _, t, _ in words), variants=_variants(words))
            say = _voiced(he_say[0] if he_say else he)
            if say != he:
                phrase["he_say"] = say
            out.append(phrase)
    return out
